$ErrorActionPreference='Stop'
$sim=Get-Process -Name jammers-simulator
@{utc=(Get-Date).ToUniversalTime().ToString('o');connections=@(Get-NetTCPConnection -OwningProcess $sim.Id -ErrorAction SilentlyContinue | Select-Object State,LocalAddress,LocalPort,RemoteAddress,RemotePort);network=@(Get-NetIPConfiguration | Where-Object {$_.IPv4DefaultGateway} | ForEach-Object {@{alias=$_.InterfaceAlias;ipv4=$_.IPv4Address.IPAddress;gateway=$_.IPv4DefaultGateway.NextHop;dns=$_.DNSServer.ServerAddresses}});dns=@(Get-DnsClientCache | Where-Object {$_.Entry -match 'cumcm|mcm|jammer|shumo'} | Select-Object Entry,Data,Type);recent_logs=@(Get-ChildItem 'C:\Users\baiwc\Downloads\Q4Practice\Jammers-simulator\JammersSimulatorData' -File | Select-Object Name,Length)} | ConvertTo-Json -Depth 7 | Out-File 'C:\Users\baiwc\Downloads\Q4V6Lite_20260913\network_probe.json' -Encoding utf8
